def shares_to_grants(apps, schema_editor):
    """The share of each token for everybody becomes its grant "everybody"."""
    token_model = apps.get_model("community", "AccessToken")
    grant_model = apps.get_model("community", "TokenGrant")
    for token in token_model.objects.filter(shared_percent__gt=0):
        grant_model.objects.create(
            token=token,
            kind="everybody",
            percent=token.shared_percent,
            hour_started=token.hour_started,
            used_in_hour=token.used_by_others_in_hour,
        )


def grants_to_shares(apps, schema_editor):
    """Back: the grant "everybody" of each token is its share again."""
    grant_model = apps.get_model("community", "TokenGrant")
    for grant in grant_model.objects.filter(kind="everybody").select_related("token"):
        grant.token.shared_percent = grant.percent
        grant.token.used_by_others_in_hour = grant.used_in_hour
        grant.token.save(update_fields=["shared_percent", "used_by_others_in_hour"])


